const { to, subject, body, isHtml, from, cc, bcc, replyTo, inReplyTo, references } = $.input;

if (!to || !subject || !body) throw new Error('to, subject, and body are required');

// Encode non-ASCII subjects per RFC 2047
function encodeSubject(s) {
  if (!/[^\x00-\x7F]/.test(s)) return s;
  const bytes = new TextEncoder().encode(s);
  let binary = '';
  bytes.forEach(b => binary += String.fromCharCode(b));
  return '=?UTF-8?B?' + btoa(binary) + '?=';
}

// Normalize literal \n sequences to real newlines, then convert to HTML
function textToHtml(text) {
  const normalized = text.replace(/\\n/g, '\n');
  const escaped = normalized.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  return '<div style="font-family:Arial,sans-serif">' + escaped.replace(/\n/g, '<br>') + '</div>';
}

const htmlBody = isHtml ? body : textToHtml(body);

// Build MIME headers
const headers = [
  'MIME-Version: 1.0',
  'From: ' + (from || 'me'),
  'To: ' + to,
  'Subject: ' + encodeSubject(subject),
  'Content-Type: text/html; charset=UTF-8'
];

if (cc) headers.push('Cc: ' + cc);
if (bcc) headers.push('Bcc: ' + bcc);
if (replyTo) headers.push('Reply-To: ' + replyTo);
if (inReplyTo) headers.push('In-Reply-To: ' + inReplyTo);
if (references) headers.push('References: ' + references);

// Join with CRLF, add blank line, then body
const mimeMessage = headers.join('\r\n') + '\r\n\r\n' + htmlBody;

// Base64url encode
const encoder = new TextEncoder();
const data = encoder.encode(mimeMessage);
let binary = '';
for (let i = 0; i < data.length; i++) binary += String.fromCharCode(data[i]);
const base64 = btoa(binary);
const base64url = base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');

const labelIds = $.input.labelIds && $.input.labelIds.length > 0 ? $.input.labelIds : ['INBOX', 'UNREAD'];
const threadId = $.input.threadId || undefined;

return { raw: base64url, labelIds, threadId };

const resp = $.steps.sendEmail.response || {};
const to = $.input.to;
const cc = $.input.cc;
const bcc = $.input.bcc;

const toList = to.split(',').map(e => e.trim()).filter(Boolean);
const ccList = cc ? cc.split(',').map(e => e.trim()).filter(Boolean) : [];
const bccList = bcc ? bcc.split(',').map(e => e.trim()).filter(Boolean) : [];
const total = toList.length + ccList.length + bccList.length;

return {
  messageId: resp.id || '',
  threadId: resp.threadId || '',
  labelIds: resp.labelIds || [],
  recipients: { to: toList, cc: ccList, bcc: bccList },
  subject: $.input.subject,
  sent: !!resp.id,
  summary: resp.id
    ? `Sent "${$.input.subject}" to ${total} recipient${total === 1 ? '' : 's'}`
    : 'Failed to send email'
};
